window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[145]={"id":"145","numero":145,"titre":"Surveillance des maladies infectieuses transmissibles","objectifs":[{"id":"145-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'une maladie infectieuse transmissible ; la définition d'épidémie/pandémie ; les indicateurs","contenu":"<p>Une <span class=\"kw-def\"><strong>maladie infectieuse transmissible</strong></span> est une infection ayant la <span class=\"kw-def\">capacité de se transmettre</span> à plusieurs individus ou entre individus.</p>\n      <table >\n        <thead><tr><th>Notion</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Endémie</span></td><td>Fréquence de cas <span class=\"kw-chiffre\">± élevée</span>, de manière <strong>habituelle et permanente</strong> (« bruit de fond »), dans une zone géographique donnée (ex. <span class=\"kw-etio\">paludisme</span> en Afrique)</td></tr>\n          <tr><td><span class=\"kw-def\">Épidémie</span></td><td><strong>Augmentation rapide</strong> de l'<span class=\"kw-def\">incidence</span> d'une maladie transmissible dans une <span class=\"kw-chiffre\">zone</span> et sur une <span class=\"kw-chiffre\">période données</span></td></tr>\n          <tr><td><span class=\"kw-def\">Pandémie</span></td><td>Propagation <strong>mondiale</strong> d'une nouvelle maladie (= épidémie à caractère mondial, ex. <span class=\"kw-etio\">COVID-19</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Indicateur clé en période épidémique — le <span class=\"kw-def\">taux d'attaque</span></strong> : il caractérise la <span class=\"kw-def\">transmissibilité</span> au cours du temps et par groupe à risque. Il se calcule :</p>\n      <ul>\n        <li><strong>Numérateur :</strong> nombre de <span class=\"kw-chiffre\">nouveaux cas</span> d'infection sur une période déterminée</li>\n        <li><strong>Dénominateur :</strong> nombre total des <span class=\"kw-chiffre\">contacts non infectés</span> au début de la période</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Exemple.</strong> Lors d'une épidémie de <span class=\"kw-etio\">fièvre Q</span> en milieu scolaire, un taux d'attaque de <span class=\"kw-chiffre\">70 %</span> chez <span class=\"kw-clinique\">les</span> élèves contre <span class=\"kw-chiffre\">16 %</span> chez les employés a orienté vers une source à proximité du réfectoire des élèves.\n      </div>","frequence":0},{"id":"145-2","rang":"B","rubrique":"Définition","titre":"Connaître les principes de la surveillance des maladies infectieuses transmissibles : organisation nationale et internationale de la surveillance, sources des données, objectifs","contenu":"<p>La <span class=\"kw-def\"><strong>surveillance</strong></span> est un « <em>processus continu et systématique de collecte, de compilation et d'analyse de données de santé, ainsi que leur diffusion à tous ceux qui ont contribué à la collecte et à tous ceux qui ont besoin d'être informés</em> ».</p>\n      <p><strong>Objectifs :</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Décrire</span> le phénomène, sa <span class=\"kw-chiffre\">fréquence</span> et sa <span class=\"kw-chiffre\">répartition temporo-spatiale</span></li>\n        <li><span class=\"kw-def\">Analyser</span> <span class=\"kw-clinique\">les</span> tendances d'<span class=\"kw-def\">incidence</span> et l'impact des <span class=\"kw-def\">politiques de prévention</span></li>\n        <li><span class=\"kw-def\">Détecter précocement</span> <span class=\"kw-clinique\">les</span> phénomènes épidémiques selon un <span class=\"kw-chiffre\">seuil d'alerte</span> (nombre de cas minimal)</li>\n      </ul>\n      <p><strong>Sources des données — deux modes de collecte :</strong></p>\n      <table >\n        <thead><tr><th>Mode</th><th>Principe</th><th>Exemple</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Surveillance passive</span></td><td>Repose sur des <span class=\"kw-bio\">données existantes</span>, sans participation volontaire ; peu coûteuse</td><td><span class=\"kw-def\">Déclaration obligatoire</span> imposée par la réglementation</td></tr>\n          <tr><td><span class=\"kw-def\">Surveillance active</span></td><td>Collecte par un <span class=\"kw-bio\">personnel dédié</span> ; données plus exhaustives et élaborées mais plus <span class=\"kw-chiffre\">coûteuses</span></td><td><span class=\"kw-def\">Réseau Sentinelles</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Niveau international :</strong> l'<span class=\"kw-def\">OMS</span> coordonne la <span class=\"kw-def\">surveillance</span> mondiale via le <span class=\"kw-def\">Règlement Sanitaire International (RSI 2005)</span> ; au niveau européen, l'<span class=\"kw-def\">ECDC</span> (Centre européen de prévention et de contrôle des maladies).</p>\n      <p class=\"obj-source\"><em>Cadre international complété depuis le Collège de Santé publique.</em></p>","frequence":0},{"id":"145-3","rang":"B","rubrique":"Définition","titre":"Connaître les principales structures et les organisations en charge de la surveillances des maladies infectieuses transmissibles en France","contenu":"<p>La <span class=\"kw-def\">surveillance</span> sanitaire française est organisée en <span class=\"kw-chiffre\">trois niveaux</span> : national, régional, départemental.</p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Structure</th><th>Rôle</th></tr></thead>\n        <tbody>\n          <tr><td rowspan=\"3\"><strong>National</strong></td><td><span class=\"kw-def\">DGS</span> (Direction générale de la santé — Ministère)</td><td>Supervision globale de la santé publique</td></tr>\n          <tr><td><span class=\"kw-def\">DUS</span> (Département des urgences sanitaires)</td><td>Gestion des crises et des situations d'<span class=\"kw-alerte\">urgence</span></td></tr>\n          <tr><td><span class=\"kw-def\">SPF</span> (<span class=\"kw-def\">Santé publique France</span>)</td><td><span class=\"kw-def\">Surveillance</span> épidémiologique et prévention des risques</td></tr>\n          <tr><td rowspan=\"4\"><strong>Régional</strong></td><td><span class=\"kw-def\">ARS</span> (Agences régionales de santé)</td><td>Pilotage et gestion des politiques de santé en région</td></tr>\n          <tr><td><span class=\"kw-def\">CIRE</span> (Cellule d'intervention régionale en <span class=\"kw-def\">épidémiologie</span>)</td><td><strong>Antenne régionale de SPF</strong> ; <span class=\"kw-def\">surveillance</span> épidémiologique locale</td></tr>\n          <tr><td><span class=\"kw-def\">CVAGS</span> (Cellule de veille, d'alerte et de gestion sanitaire, <span class=\"kw-def\">ARS</span>)</td><td>Gestion des urgences sanitaires et épidémiologiques</td></tr>\n          <tr><td><span class=\"kw-def\">CPIAS</span> (Centre d'appui à la prévention des infections associées aux soins)</td><td>Appui aux établissements pour la prévention des <span class=\"kw-etio\">infections nosocomiales</span></td></tr>\n          <tr><td><strong>Départemental</strong></td><td><span class=\"kw-def\">Préfets</span></td><td>Mise en œuvre des mesures de police sanitaire</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Acteurs de <span class=\"kw-def\">terrain</span> (<span class=\"kw-chiffre\">première ligne</span>) :</strong> <span class=\"kw-clinique\">médecins hospitaliers et libéraux</span>, <span class=\"kw-bio\">biologistes</span>, <span class=\"kw-def\">EOH</span> (équipes opérationnelles d'hygiène) — assurent le <span class=\"kw-def\">signalement</span> des maladies transmissibles.</p>","frequence":0},{"id":"145-4","rang":"B","rubrique":"Définition","titre":"Connaître les indicateurs épidémiologiques utiles dans la surveillance des maladies infectieuses","contenu":"<table >\n        <thead><tr><th>Indicateur</th><th>Définition</th><th>Intérêt</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Incidence</span></td><td>Proportion (<span class=\"kw-def\">taux d'incidence</span>) ou vitesse d'apparition (<span class=\"kw-def\">densité d'incidence</span>) de <span class=\"kw-chiffre\">nouveaux cas</span> dans une population initialement indemne</td><td>Mesure la <strong>dynamique</strong> d'une maladie</td></tr>\n          <tr><td><span class=\"kw-def\">Prévalence</span></td><td>Nombre de <span class=\"kw-chiffre\">cas existants</span> (anciens + nouveaux) à un <span class=\"kw-chiffre\">instant t</span> — « photographie » par enquête transversale</td><td>Mesure le <strong>poids</strong> d'une maladie</td></tr>\n          <tr><td><span class=\"kw-def\">Taux d'attaque</span></td><td>Nouveaux cas dans la population exposée au début de l'épidémie = <span class=\"kw-def\">taux d'incidence cumulée</span> en temps d'épidémie (courte période, &lt; <span class=\"kw-chiffre\">1 mois</span>)</td><td>Caractérise une <span class=\"kw-def\">épidémie</span> (ex. <span class=\"kw-etio\">TIAC</span>)</td></tr>\n          <tr><td><span class=\"kw-def\">Taux de létalité</span></td><td>Proportion de <span class=\"kw-chiffre\">décès parmi les malades</span> (≠ <span class=\"kw-def\">mortalité</span>, rapportée à la population totale)</td><td>Mesure la <span class=\"kw-alerte\">gravité</span> de la maladie</td></tr>\n        </tbody>\n      </table>\n      <p>Pour une enquête sur échantillon, <span class=\"kw-clinique\">les</span> indicateurs sont idéalement présentés avec leur <span class=\"kw-chiffre\">IC à 95 %</span>.</p>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique.</em></p>","frequence":0},{"id":"145-5","rang":"B","rubrique":"Définition","titre":"Connaître les indicateurs de performance des examens diagnostiques","contenu":"<p>On distingue <span class=\"kw-clinique\">les</span> performances <strong>intrinsèques</strong> (propres au test) des performances <strong>extrinsèques</strong> (dépendant du contexte).</p>\n      <table >\n        <thead><tr><th>Indicateur</th><th>Définition</th><th>Propriété</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Sensibilité (Se)</span></td><td>Probabilité que le test soit <span class=\"kw-bio\">positif</span> si le sujet est <strong>malade</strong> ; estimée par la proportion de <span class=\"kw-bio\">vrais positifs</span> parmi <span class=\"kw-clinique\">les</span> malades</td><td><strong>Intrinsèque</strong> — un test très sensible (Se = <span class=\"kw-chiffre\">1</span>) <strong>exclut</strong> la maladie (test négatif fiable)</td></tr>\n          <tr><td><span class=\"kw-def\">Spécificité (Sp)</span></td><td>Probabilité que le test soit <span class=\"kw-bio\">négatif</span> si le sujet est <strong>sain</strong> ; proportion de <span class=\"kw-bio\">vrais négatifs</span> parmi <span class=\"kw-clinique\">les</span> non-malades</td><td><strong>Intrinsèque</strong> — un test très spécifique <strong>confirme</strong> la maladie (test positif fiable)</td></tr>\n          <tr><td><span class=\"kw-def\">VPP</span></td><td>Probabilité d'être <strong>malade</strong> si le test est <span class=\"kw-bio\">positif</span></td><td><strong>Extrinsèque</strong> — <span class=\"kw-alerte\">dépend de la prévalence</span></td></tr>\n          <tr><td><span class=\"kw-def\">VPN</span></td><td>Probabilité d'être <strong>sain</strong> si le test est <span class=\"kw-bio\">négatif</span></td><td><strong>Extrinsèque</strong> — <span class=\"kw-alerte\">dépend de la prévalence</span></td></tr>\n          <tr><td><span class=\"kw-def\">Rapports de vraisemblance (RV+ / RV−)</span></td><td>Combinent Se et Sp pour déduire la probabilité <span class=\"kw-bio\">post-test</span> (théorème de Bayes, nomogramme de Fagan)</td><td><strong>Intrinsèques</strong> — indépendants de la <span class=\"kw-def\">prévalence</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Se/Sp sont <strong>intrinsèques</strong> (constantes). En revanche, quand la <span class=\"kw-def\">prévalence diminue</span>, la <span class=\"kw-def\">VPP diminue</span> et la <span class=\"kw-def\">VPN augmente</span> — d'où l'intérêt de tester des populations à risque.\n      </div>\n      <p class=\"obj-source\"><em>Complété depuis le Collège de Santé publique.</em></p>","frequence":0},{"id":"145-6","rang":"B","rubrique":"Définition","titre":"Connaître les quatre principales missions de Santé Publique France en matière de maladies infectieuses","contenu":"<p><span class=\"kw-def\"><strong>Santé publique France (SPF)</strong></span> est un établissement public né de la fusion de l'<span class=\"kw-def\">InVS</span> (veille sanitaire), l'<span class=\"kw-def\">INPES</span> (prévention/promotion de la santé) et l'<span class=\"kw-def\">EPRUS</span> (réponse aux urgences sanitaires). Elle dispose d'un réseau régional, <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">CIRE</span>, situées au sein des <span class=\"kw-def\">ARS</span>.</p>\n      <table >\n        <thead><tr><th>Mission</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">1. Anticiper</span></td><td><strong><span class=\"kw-def\">Surveillance</span></strong> et observation permanente de l'état de santé (indicateurs de <span class=\"kw-chiffre\">morbi-mortalité</span>), appuyée par <span class=\"kw-clinique\">les</span> réseaux (<span class=\"kw-def\">Sentinelles</span>, registres)</td></tr>\n          <tr><td><span class=\"kw-def\">2. Comprendre</span></td><td><strong>Veille et vigilance sanitaire</strong> ; SPF est chargée de l'<span class=\"kw-def\">infectiovigilance</span> (veille des <span class=\"kw-etio\">infections associées aux soins</span>) et des <span class=\"kw-def\">maladies à déclaration obligatoire</span></td></tr>\n          <tr><td><span class=\"kw-def\">3. Agir / Promouvoir</span></td><td><strong>Promotion de la santé</strong>, action sur <span class=\"kw-clinique\">les</span> environnements, mise en œuvre des <span class=\"kw-def\">programmes de prévention</span></td></tr>\n          <tr><td><span class=\"kw-def\">4. Alerter &amp; gérer les crises</span></td><td><span class=\"kw-alerte\">Alerte sanitaire</span> (information du <strong>ministre chargé de la Santé</strong> en cas de <span class=\"kw-alerte\">menace</span>), contribution à la <strong>gestion des crises sanitaires</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Piège.</strong> SPF <strong>n'a PAS</strong> pour mission l'<span class=\"kw-ci\">évaluation médico-économique</span> (distracteur classique).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 181 — Sécurité sanitaire des produits - Veille sanitaire · 4 — Infection nosocomiale</em></p>","frequence":0},{"id":"145-7","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie des maladies transmissibles interhumaines, la physiopathologie des maladies transmissibles d'origine environnementale","contenu":"<table >\n        <thead><tr><th>Élément</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Agent infectieux</span></td><td>Micro-organisme caractérisé par sa <span class=\"kw-bio\">virulence</span> (capacité à engendrer une infection) et sa <span class=\"kw-bio\">résistance aux traitements</span></td></tr>\n          <tr><td><span class=\"kw-def\">Réservoir</span></td><td>Lieu écologique où vit et se multiplie l'agent ; peut être l'<strong>homme</strong> ou l'<strong>environnement</strong></td></tr>\n          <tr><td><span class=\"kw-def\">Hôte</span></td><td>Individu <span class=\"kw-clinique\">réceptif</span> (immunité, lésions cutanées, comportements à risque)</td></tr>\n          <tr><td><span class=\"kw-def\">Vecteur</span></td><td>Support <strong>animé ou inanimé</strong> qui transporte l'agent pathogène</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Réservoir <span class=\"kw-def\">endogène</span> — le microbiote :</strong> l'organisme héberge <span class=\"kw-chiffre\">10¹³ à 10¹⁴</span> micro-organismes (peau, muqueuses). Ils deviennent pathogènes en cas de :</p>\n      <ul>\n        <li><strong>Prolifération excessive</strong> (ex. <span class=\"kw-etio\">Candida</span> ou <span class=\"kw-etio\">C. difficile</span> après <span class=\"kw-ttt\">antibiothérapie</span>)</li>\n        <li><strong>Déficit immunitaire</strong> (<span class=\"kw-etio\">infections opportunistes</span>)</li>\n        <li><strong>Effraction des barrières</strong> (cathéter, <span class=\"kw-ttt\">chirurgie</span>, drogues injectées)</li>\n      </ul>\n      <p><strong>Infections <span class=\"kw-def\">exogènes</span> (réservoir hors de l'organisme) :</strong></p>\n      <ul>\n        <li><strong>Réservoir animal</strong> (<span class=\"kw-def\">zoonoses</span>) : <span class=\"kw-etio\">salmonelloses non typhiques</span>, <span class=\"kw-etio\">listériose</span>, <span class=\"kw-etio\">fièvre jaune</span></li>\n        <li><strong>Réservoir environnemental</strong> : sol (<span class=\"kw-etio\">tétanos</span>), <span class=\"kw-def\">air</span> (<span class=\"kw-etio\">aspergillose</span>), eau (<span class=\"kw-etio\">légionellose</span>)</li>\n        <li><strong>Réservoir humain</strong> (le plus fréquent) : éradication possible si réservoir strictement humain (<span class=\"kw-etio\">variole</span>, <span class=\"kw-etio\">poliomyélite</span>, <span class=\"kw-etio\">rougeole</span>)</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong><span class=\"kw-etio\">Colonisation</span> → infection.</strong> <span class=\"kw-bio\">Germes pathogènes stricts</span> (<span class=\"kw-etio\">streptocoque A</span>, <span class=\"kw-etio\">choléra</span>, <span class=\"kw-etio\">Ebola</span>) = infection systématique ; <span class=\"kw-bio\">colonisation tolérée</span> = flore commensale sans infection.\n      </div>","frequence":0},{"id":"145-8","rang":"A","rubrique":"Physiopathologie","titre":"Connaître les modes de la transmission des maladies infectieuses (contact, gouttelettes, air, environnement)","contenu":"<p><strong>Transmission directe</strong> — distinction majeure <span class=\"kw-def\">air</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-def\">gouttelettes</span> :</p>\n      <table >\n        <thead><tr><th>Mode</th><th>Mécanisme</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Air (aéroportée)</span></td><td>Particules de <strong>petite taille</strong>, restent en suspension plusieurs minutes ; distance <span class=\"kw-chiffre\">&gt; 1 mètre</span></td><td><span class=\"kw-etio\">Tuberculose (BK)</span>, <span class=\"kw-etio\">rougeole</span>, <span class=\"kw-etio\">varicelle</span></td></tr>\n          <tr><td><span class=\"kw-def\">Gouttelettes</span> (de Pflügge)</td><td>Particules <strong>plus grandes</strong>, sédimentent vite ; courte distance <span class=\"kw-chiffre\">&lt; 1-2 m</span></td><td><span class=\"kw-etio\">Méningocoque</span>, <span class=\"kw-etio\">grippe</span>, <span class=\"kw-etio\">coqueluche</span>, <span class=\"kw-etio\">COVID-19</span></td></tr>\n          <tr><td><span class=\"kw-def\">Contact direct</span> (manuporté)</td><td>Mains, muqueuses, réservoir animal</td><td>Infections respiratoires, <span class=\"kw-def\">féco-oral</span>, <span class=\"kw-etio\">BMR</span>, <span class=\"kw-etio\">gale</span>, <span class=\"kw-etio\">rage</span></td></tr>\n          <tr><td><span class=\"kw-def\">Sexuelle</span></td><td>Rapports</td><td><span class=\"kw-etio\">Syphilis</span>, <span class=\"kw-etio\">Chlamydia</span>, <span class=\"kw-etio\">HPV</span>, <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">VHB</span></td></tr>\n          <tr><td><span class=\"kw-def\">Sanguine</span></td><td>Transfusion, exposition au sang</td><td><span class=\"kw-etio\">VHC</span>, <span class=\"kw-etio\">VHB</span>, <span class=\"kw-etio\">VIH</span></td></tr>\n          <tr><td><span class=\"kw-def\">Verticale</span> (mère-enfant)</td><td><span class=\"kw-ci\">Grossesse</span> ou accouchement</td><td><span class=\"kw-etio\">Toxoplasmose</span>, <span class=\"kw-etio\">VIH</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>Transmission indirecte / environnement :</strong></p>\n      <table >\n        <thead><tr><th>Voie</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Eau &amp; aliments</span></td><td><span class=\"kw-etio\">Typhoïde</span> ; <span class=\"kw-etio\">choléra</span> ; gastro-entérites</td></tr>\n          <tr><td><span class=\"kw-def\">Eau en aérosol</span></td><td><span class=\"kw-etio\">Légionellose</span></td></tr>\n          <tr><td><span class=\"kw-def\">Sol</span></td><td><span class=\"kw-etio\">Tétanos</span> ; parasitoses digestives</td></tr>\n          <tr><td><span class=\"kw-def\">Arthropodes vecteurs</span></td><td>\n            <strong>Moustiques :</strong> <span class=\"kw-etio\">dengue</span> ; <span class=\"kw-etio\">paludisme</span> ; <span class=\"kw-etio\">fièvre jaune</span><br>\n            <strong>Tiques :</strong> <span class=\"kw-etio\">borréliose de Lyme</span><br>\n            <strong>Mouches :</strong> <span class=\"kw-etio\">onchocercose</span>\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant clé.</strong> <span class=\"kw-etio\">BK</span> / <span class=\"kw-etio\">rougeole</span> / <span class=\"kw-etio\">varicelle</span> = transmission <strong><span class=\"kw-def\">air</span></strong> (&gt; 1 m). <span class=\"kw-etio\">Méningocoque</span> / <span class=\"kw-etio\">grippe</span> = <strong><span class=\"kw-def\">gouttelettes</span></strong> (&lt; 1-2 m). Piège EDN fréquent.\n      </div>","frequence":0},{"id":"145-9","rang":"B","rubrique":"Epidémiologie","titre":"Classer les principales maladies infectieuses transmissibles en fonction de leur mode de transmission","contenu":"<table >\n        <thead><tr><th>Transmission</th><th>Sous-catégorie</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td rowspan=\"4\"><strong>Interhumaine directe</strong></td><td><span class=\"kw-def\">Contact</span> (cutané / muqueux)</td><td>\n            <strong>Cutané :</strong> <span class=\"kw-etio\">staphylococcies</span> ; <span class=\"kw-etio\">ectoparasitoses</span><br>\n            <strong>Muqueux / sang :</strong> <span class=\"kw-etio\">IST</span> ; <span class=\"kw-etio\">VIH</span> ; <span class=\"kw-etio\">VHB</span> ; <span class=\"kw-etio\">VHC</span> ; <span class=\"kw-etio\">Herpesviridae</span> (<span class=\"kw-etio\">EBV</span>, VZV, HSV)\n          </td></tr>\n          <tr><td><span class=\"kw-def\">Gouttelettes</span></td><td><span class=\"kw-etio\">Méningocoque</span> ; <span class=\"kw-etio\">oreillons</span> ; <span class=\"kw-etio\">coqueluche</span> ; <span class=\"kw-etio\">COVID-19</span> ; <span class=\"kw-etio\">grippe</span> ; <span class=\"kw-etio\">VRS</span></td></tr>\n          <tr><td><span class=\"kw-def\">Air</span></td><td><span class=\"kw-etio\">BK</span> ; <span class=\"kw-etio\">rougeole</span> ; <span class=\"kw-etio\">varicelle</span></td></tr>\n          <tr><td><span class=\"kw-def\">Mère-enfant</span> (verticale)</td><td><span class=\"kw-etio\">VIH</span> ; <span class=\"kw-etio\">VHB</span> ; <span class=\"kw-etio\">toxoplasmose</span> ; <span class=\"kw-etio\">rubéole</span> ; <span class=\"kw-etio\">streptocoque B</span></td></tr>\n          <tr><td rowspan=\"2\"><strong>Interhumaine indirecte</strong></td><td>Vecteur <span class=\"kw-def\">animé</span></td><td><span class=\"kw-etio\">Paludisme</span> ; <span class=\"kw-etio\">arboviroses</span></td></tr>\n          <tr><td>Vecteur <span class=\"kw-def\">inanimé</span> (eau, aliments)</td><td><span class=\"kw-etio\">VHA</span> ; <span class=\"kw-etio\">VHE</span> ; <span class=\"kw-etio\">poliovirus</span> ; <span class=\"kw-etio\">amibiase</span></td></tr>\n          <tr><td rowspan=\"3\"><strong>Environnementale</strong></td><td>Directe</td><td><span class=\"kw-def\">Zoonoses</span> (<span class=\"kw-etio\">rage</span>) ; inoculation (<span class=\"kw-etio\">tétanos</span>) ; <span class=\"kw-def\">air</span> (<span class=\"kw-etio\">aspergillose</span>)</td></tr>\n          <tr><td>Indirecte — vecteur animé</td><td><span class=\"kw-etio\">Rickettsioses</span> ; <span class=\"kw-etio\">borrélioses</span> ; <span class=\"kw-etio\">arboviroses</span></td></tr>\n          <tr><td>Indirecte — vecteur inanimé</td><td><span class=\"kw-etio\">Légionellose</span> (eau) ; <span class=\"kw-etio\">salmonellose</span> ; <span class=\"kw-etio\">listériose</span> (aliments)</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"145-10","rang":"A","rubrique":"Epidémiologie","titre":"**Maladies à déclaration obligatoire : connaître les principes, le fonctionnement, la source d'information, les deux principales étapes du circuit et les acteurs impliqués**","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\"><strong>maladies à déclaration obligatoire (MDO)</strong></span> sont au nombre de <span class=\"kw-chiffre\">36</span>, dont <span class=\"kw-chiffre\">34 infectieuses</span> (transmissibles pour la plupart) et <span class=\"kw-chiffre\">2 non infectieuses</span> : le <span class=\"kw-etio\">mésothéliome</span> et le <span class=\"kw-etio\">saturnisme</span> de l'enfant. La liste est fixée par <strong>décision du ministre de la Santé</strong> et actualisable.</p>\n\n      <p><strong><span class=\"kw-clinique\">Les</span> deux étapes du circuit (à connaître ⭐) :</strong></p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-def\">Signalement</span></th><th><span class=\"kw-def\">Notification</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Par qui ?</strong></td><td>Médecins et biologistes (niveau local)</td><td>Médecins et biologistes (niveau local)</td></tr>\n          <tr><td><strong>Anonymat ?</strong></td><td><span class=\"kw-alerte\">Nominatif</span> (patient et entourage informés)</td><td><span class=\"kw-def\">Anonymisé</span> (à la source ou par le médecin inspecteur de l'<span class=\"kw-def\">ARS</span>)</td></tr>\n          <tr><td><strong>Quand ?</strong></td><td><span class=\"kw-alerte\">Sans délai, en urgence</span> (parfois avant confirmation du diagnostic)</td><td>Dans un <span class=\"kw-chiffre\">2nd temps</span> (pas urgent ; après confirmation — sauf ex. <span class=\"kw-etio\">tuberculose</span> suspectée)</td></tr>\n          <tr><td><strong>Comment ?</strong></td><td>Tout moyen (<strong>fax</strong>, mail, téléphone)</td><td><strong>Formulaires spécifiques</strong> (courrier / voie électronique)</td></tr>\n          <tr><td><strong>À qui ?</strong></td><td>Médecin inspecteur de l'<span class=\"kw-def\">ARS</span></td><td>Médecin inspecteur de l'<span class=\"kw-def\">ARS</span> → puis <span class=\"kw-def\">Santé publique France</span></td></tr>\n          <tr><td><strong>Objectif</strong></td><td>Mesures de prévention <strong>autour du cas</strong> (prophylaxie, <span class=\"kw-ttt\">vaccination</span>, invest<span class=\"kw-chiffre\">iga</span>tion)</td><td><strong><span class=\"kw-def\">Surveillance</span> épidémiologique</strong></td></tr>\n        </tbody>\n      </table>\n      <p>Le <span class=\"kw-def\">signalement</span> concerne la majorité des MDO <strong>sauf</strong> celles sans mesure d'<span class=\"kw-alerte\">urgence</span> (<span class=\"kw-etio\">VHB aiguë</span>, <span class=\"kw-etio\">VIH</span>, <span class=\"kw-etio\">mésothéliome</span>, <span class=\"kw-etio\">tétanos</span>). La <span class=\"kw-def\">notification</span> concerne <strong>toutes</strong> <span class=\"kw-clinique\">les</span> MDO sans exception. Les données nominatives sont détruites par l'<span class=\"kw-def\">ARS</span> après invest<span class=\"kw-chiffre\">iga</span>tion.</p>\n\n      <p><strong>Source d'information :</strong> le <span class=\"kw-def\">déclarant</span> (médecin / biologiste, public ou privé).</p>\n      <p><strong><span class=\"kw-clinique\">Les</span> 3 acteurs :</strong></p>\n      <ul>\n        <li><strong>Déclarants locaux :</strong> <span class=\"kw-clinique\">médecins libéraux et hospitaliers</span>, <span class=\"kw-bio\">biologistes</span>, responsables de labos</li>\n        <li><strong>Médecins inspecteurs de santé publique des <span class=\"kw-def\">ARS</span> :</strong> niveau départemental, prévention et diminution de la diffusion</li>\n        <li><strong>Épidémiologistes de <span class=\"kw-def\">Santé publique France</span> :</strong> niveau national (en lien avec <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">CIRE</span>) ; centralisent, analysent et transmettent aux pouvoirs publics avec recommandations</li>\n      </ul>\n      <div class=\"callout callout-danger\">\n        <strong>Distracteurs — NE sont PAS des MDO.</strong> <span class=\"kw-etio\">Syphilis</span>, <span class=\"kw-etio\">gonocoque</span>, <span class=\"kw-etio\">hépatite B chronique</span>, <span class=\"kw-etio\">VHC</span>, <span class=\"kw-etio\">VHD</span>, <span class=\"kw-etio\">VHE</span>, <span class=\"kw-etio\">méningite à pneumocoque</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 151 — <span class=\"kw-clinique\">Méningite</span> - méningoencéphalite · 159 — <span class=\"kw-etio\">Tuberculose</span> enfant / Adulte · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":1},{"id":"145-11","rang":"B","rubrique":"Définition","titre":"Connaître la définition des centres nationaux de référence","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\"><strong>centres nationaux de référence (CNR)</strong></span> sont des <span class=\"kw-bio\">laboratoires</span> localisés au sein d'établissements publics ou privés de santé, d'enseignement ou de recherche.</p>\n      <table >\n        <thead><tr><th>Aspect</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Nomination</span></td><td>Par le <strong>ministre de la Santé</strong> sur proposition de <span class=\"kw-def\">Santé publique France</span>, pour <span class=\"kw-chiffre\">3 à 5 ans</span> ; coordonnés et financés par SPF</td></tr>\n          <tr><td><span class=\"kw-def\">Expertise</span></td><td><span class=\"kw-bio\">Microbiologie</span> : identification et confirmation des agents pathogènes ; développement et validation d'examens de biologie médicale</td></tr>\n          <tr><td><span class=\"kw-def\">Conseil</span></td><td>Conseil scientifique et technique au ministre, à SPF et aux professionnels de santé</td></tr>\n          <tr><td><span class=\"kw-def\">Surveillance</span></td><td>Contribution à la <span class=\"kw-def\">surveillance</span> épidémiologique via l'animation d'un <strong>réseau de laboratoires</strong></td></tr>\n          <tr><td><span class=\"kw-alerte\">Alerte</span></td><td><strong>Alerte immédiate</strong> de SPF, du ministère et de l'<span class=\"kw-def\">ARS</span> devant toute <span class=\"kw-alerte\">menace</span> pour la santé de la population</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"145-12","rang":"A","rubrique":"Définition","titre":"**Connaître les principes et les principales mesures de prévention des maladies infectieuses transmissibles interhumaines et à transmission d'origine environnementale en collectivité**","contenu":"<p>La prévention repose sur l'<strong>interruption de la chaîne de transmission</strong>, adaptée au mode de transmission de l'agent.</p>\n      <p><strong>1. <span class=\"kw-def\">Précautions standard</span></strong> (socle, pour tous) :</p>\n      <ul>\n        <li><span class=\"kw-def\">Hygiène des mains</span> (solution hydro-alcoolique +++)</li>\n        <li>Port de <span class=\"kw-def\">gants</span>, <span class=\"kw-def\">masque</span>, surblouse selon le risque</li>\n        <li>Gestion du matériel souillé et des excreta</li>\n      </ul>\n      <p><strong>2. <span class=\"kw-def\">Précautions complémentaires</span></strong> selon le mode de transmission :</p>\n      <table >\n        <thead><tr><th>Type</th><th>Mesure</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Contact</span></td><td>Chambre individuelle, gants + surblouse</td><td><span class=\"kw-etio\">BMR</span>, <span class=\"kw-etio\">gale</span>, <span class=\"kw-etio\">C. difficile</span></td></tr>\n          <tr><td><span class=\"kw-def\">Gouttelettes</span></td><td><span class=\"kw-def\">Masque chirurgical</span> (&lt; <span class=\"kw-chiffre\">1-2 m</span>)</td><td><span class=\"kw-etio\">Méningocoque</span>, <span class=\"kw-etio\">grippe</span>, <span class=\"kw-etio\">coqueluche</span></td></tr>\n          <tr><td><span class=\"kw-def\">Air</span></td><td>Chambre à <strong>pression négative</strong> + <span class=\"kw-def\">masque FFP2</span></td><td><span class=\"kw-etio\">Tuberculose</span>, <span class=\"kw-etio\">rougeole</span>, <span class=\"kw-etio\">varicelle</span></td></tr>\n        </tbody>\n      </table>\n      <p><strong>3. Autres leviers en collectivité :</strong></p>\n      <ul>\n        <li><span class=\"kw-def\">Vaccination</span> (rougeole, <span class=\"kw-etio\">méningocoque</span>, coqueluche)</li>\n        <li><span class=\"kw-def\">Prophylaxie post-exposition</span> des sujets contacts (ex. <span class=\"kw-ttt\">antibioprophylaxie</span> autour d'un cas de <span class=\"kw-etio\">méningocoque</span>)</li>\n        <li><span class=\"kw-def\">Éviction</span> des collectivités (voir objectif dédié)</li>\n        <li><strong>Transmission environnementale :</strong> traitement de l'<span class=\"kw-bio\">eau</span> (<span class=\"kw-etio\">légionelle</span>), sécurité <span class=\"kw-bio\">alimentaire</span> (<span class=\"kw-etio\">listéria</span>, <span class=\"kw-etio\">salmonelle</span>), lutte <span class=\"kw-def\">antivectorielle</span></li>\n      </ul>\n      <p class=\"obj-source\"><em>Mesures de prévention complétées depuis le Collège de Santé publique.</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 146 — <span class=\"kw-ttt\">Vaccination</span> · 4 — Infection nosocomiale</em></p>","frequence":1},{"id":"145-13","rang":"A","rubrique":"Epidémiologie","titre":"Savoir qu'il existe des maladies devant faire l'objet de mesures d'éviction et savoir où en trouver la liste","contenu":"<div class=\"callout callout-info\">\n        <strong>Principe.</strong> Certaines maladies transmissibles imposent une <span class=\"kw-def\">éviction des collectivités</span> (crèches, écoles). Même hors recommandation officielle, la fréquentation à la <strong>phase aiguë</strong> n'est pas souhaitable. La liste figure dans le <strong>guide SPILF / <span class=\"kw-def\">Santé publique France</span></strong> (arrêté relatif aux évictions scolaires).\n      </div>\n      <table >\n        <thead><tr><th>Maladie</th><th>Durée d'éviction</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Angine streptococcique / scarlatine</span></td><td><span class=\"kw-chiffre\">2 jours</span> après le début de l'<span class=\"kw-ttt\">antibiothérapie</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Rougeole</span></td><td><span class=\"kw-chiffre\">5 jours</span> après le début de l'<span class=\"kw-clinique\">éruption</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Coqueluche</span></td><td><span class=\"kw-chiffre\">3 jours</span> après <span class=\"kw-ttt\">azithromycine</span> ; <span class=\"kw-chiffre\">5 jours</span> après <span class=\"kw-ttt\">clarithromycine</span> / <span class=\"kw-ttt\">cotrimoxazole</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Gale commune</span></td><td><span class=\"kw-chiffre\">3 jours</span> après le début du traitement</td></tr>\n          <tr><td><span class=\"kw-etio\">Impétigo étendu</span></td><td><span class=\"kw-chiffre\">3 jours</span> après début de l'<span class=\"kw-ttt\">antibiothérapie</span> (pas d'éviction si lésions limitées / protégées)</td></tr>\n          <tr><td><span class=\"kw-etio\">Hépatite A</span></td><td><span class=\"kw-chiffre\">10 jours</span></td></tr>\n          <tr><td><span class=\"kw-etio\">GEA à E. coli entérohémorragique / shigelles</span></td><td>Jusqu'à <span class=\"kw-chiffre\">2 coprocultures négatives</span> à <span class=\"kw-chiffre\">≥ 24 h</span> d'intervalle (<span class=\"kw-chiffre\">≥ 48 h</span> après arrêt de l'ATB)</td></tr>\n          <tr><td><span class=\"kw-etio\">Méningite à méningocoque</span></td><td>Jusqu'à <strong>guérison clinique</strong></td></tr>\n          <tr><td><span class=\"kw-etio\">Teigne du cuir chevelu</span> / <span class=\"kw-etio\">tuberculose</span></td><td>Jusqu'à <strong>certificat médical de non-contagiosité</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\">\n        <strong>PAS d'éviction (piège).</strong> <span class=\"kw-etio\">Otites</span>, angine non strepto, rhinopharyngite, bronchiolite, GEA virales / salmonelles mineures, <span class=\"kw-etio\">grippe saisonnière</span>, gingivostomatite herpétique, <span class=\"kw-etio\">méningite à pneumocoque</span> / <span class=\"kw-etio\">virale</span>, <span class=\"kw-etio\">MNI</span>, <span class=\"kw-etio\">oreillons</span>, <span class=\"kw-etio\">rubéole</span>, <span class=\"kw-etio\">varicelle</span>, roséole, pédiculose, verrues, <span class=\"kw-etio\">VIH</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 159 — <span class=\"kw-etio\">Tuberculose</span> enfant / Adulte · 151 — <span class=\"kw-clinique\">Méningite</span> - méningoencéphalite</em></p>","frequence":0},{"id":"145-14","rang":"B","rubrique":"Définition","titre":"Connaître la définition d'un réseau « sentinelle »","contenu":"<p>Le <span class=\"kw-def\"><strong>réseau Sentinelles</strong></span> est un réseau de recherche et de veille en <span class=\"kw-def\">soins de premiers recours</span> (médecine générale et pédiatrie) en France métropolitaine, sous tutelle conjointe de l'<span class=\"kw-def\">Inserm</span> et de <span class=\"kw-def\">Sorbonne Université</span>.</p>\n      <table >\n        <thead><tr><th>Aspect</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Type</span></td><td><span class=\"kw-def\">Surveillance active</span> en temps réel d'événements <strong>non couverts</strong> par la déclaration obl<span class=\"kw-chiffre\">iga</span>toire (<span class=\"kw-etio\">grippe saisonnière</span>, <span class=\"kw-etio\">gastro-entérite aiguë</span>…)</td></tr>\n          <tr><td><span class=\"kw-def\">Médecins membres</span></td><td>≈ <span class=\"kw-chiffre\">1300 médecins généralistes</span> libéraux + <span class=\"kw-chiffre\">116 pédiatres</span> (« médecins Sentinelles »)</td></tr>\n          <tr><td><span class=\"kw-def\">Fonctionnement</span></td><td>Transmission permanente des données via Internet à un <strong>centre coordonnateur</strong> (Inserm)</td></tr>\n          <tr><td><span class=\"kw-def\">Restitution</span></td><td><span class=\"kw-chiffre\">Bulletin hebdomadaire</span> diffusé sur le site <strong>Sentiweb</strong> (rétro-information ; <span class=\"kw-def\">suivi</span> quasi temps réel des épidémies)</td></tr>\n        </tbody>\n      </table>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-145.pdf","label":"Pilly étudiant 2023 — item 145 (Surveillance des maladies infectieuses)"}],"cards":[]};